    }

    live.current = live.current.filter(burst => now - burst.started < BURST_MS)
  })

  return (
    <group>
      {Array.from({ length: BURST_POOL }, (_, index) => (
        <mesh
          key={index}
          ref={(mesh) => { rings.current[index] = mesh }}
          visible={false}
        >
          <ringGeometry args={[0.84, 1, 48]} />
          <meshBasicMaterial
            color="#49e0a6"
            transparent
            opacity={0}
            side={DoubleSide}
            blending={AdditiveBlending}
            depthWrite={false}
            toneMapped={false}
          />
        </mesh>
      ))}
    </group>
  )
