'use client'

import { Html, OrbitControls } from '@react-three/drei'
import { useFrame } from '@react-three/fiber'
import { useEffect, useMemo, useRef, type ReactNode } from 'react'
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Color,
  Vector3,
  type Mesh,
  type Points,
} from 'three'
import type { Agent, RunEvent } from '@/lib/contract'
import { usePrefersReducedMotion } from '@/lib/motion'
import { SEVERITY_COLOR } from '@/lib/palette'
import { discoverLanes, laneOf, laneY, stageOf, STAGES } from '@/lib/pipeline'
import { createGlowMaterial } from '@/components/three/glow'
import { Stage as Canvas3D } from '@/components/three/Stage'

/** How many particles can be in flight at once. */
const POOL = 420

/** Flight time of one particle between two stages, in milliseconds. */
const FLIGHT_MS = 1_500

/** Colour per event kind for the particles and the lane pulses. */
const KIND_COLOR: Record<string, string> = {
  step: '#5fa8ff',
  tool: '#4fd8ff',
  delegation: '#9b7bff',
  directive: '#ffbe5c',
  certificate: '#49e0a6',
  finding: '#ff3f6b',
  merge: '#ff8a6b',
  refusal: '#ff8a3d',
}

/** One particle in flight along the pipeline. */
interface Particle {
  from: Vector3
  to: Vector3
  started: number
  color: Color
}

