/**
 * The roster edges as one additive line layer, plus a brighter layer for the
 * selected agent's own relationships.
 * @param props - The roster and its computed layout.
 * @returns The edge scene contents.
 */
function GraphEdges({ roster, layout }: { roster: Roster, layout: GraphLayout }): ReactNode {
  const selectedId = useDeck(state => state.selectedAgentId)
  const highlight = useRef<LineSegments>(null)

  const geometry = useMemo(() => {
    const usable = roster.edges.filter(edge => layout.index.has(edge.from) && layout.index.has(edge.to))
    const positions = new Float32Array(usable.length * 6)
    const colors = new Float32Array(usable.length * 6)
    const colour = new Color()
    for (const [index, edge] of usable.entries()) {
      const from = layout.nodes[layout.index.get(edge.from) ?? 0]
      const to = layout.nodes[layout.index.get(edge.to) ?? 0]
      if (from === undefined || to === undefined) continue
      positions.set([from.x, from.y, from.z, to.x, to.y, to.z], index * 6)
      colour.set(EDGE_COLOR[edge.kind])
      colors.set([colour.r, colour.g, colour.b, colour.r, colour.g, colour.b], index * 6)
    }
    const built = new BufferGeometry()
    built.setAttribute('position', new BufferAttribute(positions, 3))
    built.setAttribute('color', new BufferAttribute(colors, 3))
    return built
  }, [roster.edges, layout])

  useEffect(() => () => geometry.dispose(), [geometry])

  const selectedGeometry = useMemo(() => {
    const built = new BufferGeometry()
    if (selectedId === undefined) {
      built.setAttribute('position', new BufferAttribute(new Float32Array(0), 3))
      built.setAttribute('color', new BufferAttribute(new Float32Array(0), 3))
      return built
    }
    const related = roster.edges.filter(edge => edge.from === selectedId || edge.to === selectedId)
    const positions = new Float32Array(related.length * 6)
    const colors = new Float32Array(related.length * 6)
    const colour = new Color()
    for (const [index, edge] of related.entries()) {
      const from = layout.nodes[layout.index.get(edge.from) ?? 0]
      const to = layout.nodes[layout.index.get(edge.to) ?? 0]
      if (from === undefined || to === undefined) continue
      positions.set([from.x, from.y, from.z, to.x, to.y, to.z], index * 6)
      colour.set(EDGE_COLOR[edge.kind])
      colors.set([colour.r, colour.g, colour.b, colour.r, colour.g, colour.b], index * 6)
    }
    built.setAttribute('position', new BufferAttribute(positions, 3))
    built.setAttribute('color', new BufferAttribute(colors, 3))
    return built
  }, [roster.edges, layout, selectedId])

  useEffect(() => () => selectedGeometry.dispose(), [selectedGeometry])

  return (
    <group>
      <lineSegments geometry={geometry} frustumCulled={false}>
        <lineBasicMaterial
          vertexColors
          transparent
          opacity={selectedId === undefined ? 0.2 : 0.07}
          blending={AdditiveBlending}
          depthWrite={false}
          toneMapped={false}
        />
      </lineSegments>
      <lineSegments ref={highlight} geometry={selectedGeometry} frustumCulled={false}>
        <lineBasicMaterial
          vertexColors
          transparent
          opacity={0.9}
          blending={AdditiveBlending}
          depthWrite={false}
          toneMapped={false}
